  // the credential or the catalog changes, so the picker only offers choices
  // that work for this account.
  const withoutDenied = (providerID: string, models: ModelMap): ModelMap => {
    if (state.deniedModels.size === 0) return models;
    const kept: ModelMap = {};
    for (const [id, model] of Object.entries(models)) {
      if (!state.deniedModels.has(`${providerID}/${id}`)) kept[id] = model;
    }
    return kept;
