      state.outputLimits.set(`${DEFENSE_PROVIDER_ID}/${id}`, model.limit.output);
      state.contextLimits.set(`${DEFENSE_PROVIDER_ID}/${id}`, model.limit.context);
      if (model.modalities.input.includes("image")) {
